<?php
require 'config.php';require_login();$page_title='Projects';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){require_admin();csrf_check();$name=trim($_POST['project_name']??'');$date=$_POST['start_date']??'';$dt=DateTime::createFromFormat('!Y-m-d',$date);if(strlen($name)<2||strlen($name)>100||!$dt||$dt->format('Y-m-d')!==$date){flash('Enter a project name and a valid start date.','error');header('Location: projects.php');exit;}try{$pdo->prepare('INSERT INTO projects(project_name,start_date) VALUES(?,?)')->execute([$name,$date]);flash('Project created.');}catch(PDOException $e){flash('Project name already exists or could not be saved.','error');}header('Location: projects.php');exit;}
$rows=$pdo->query('SELECT p.*,COUNT(ep.employee_id) assigned_count FROM projects p LEFT JOIN employee_projects ep ON ep.project_id=p.project_id GROUP BY p.project_id ORDER BY p.start_date DESC')->fetchAll();include 'includes/header.php';?>
<section class="hero"><div><p class="eyebrow">WORK ALLOCATION</p><h1>Projects</h1><p class="muted">Track projects and see how many employees are assigned to each.</p></div><button class="btn outline print-trigger" onclick="window.print()">Print directory</button></section>
<?php if(is_admin()): ?><section class="panel"><div class="panel-head"><h2>Add a project</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div><label>Project name<input name="project_name" maxlength="100" required ></label></div><div><label>Start date<input type="date" name="start_date" required value="<?=e(date('Y-m-d'))?>"></label></div><div class="full actions"><button class="btn primary">Create project</button></div></form></section><?php endif; ?>
<section class="panel"><div class="panel-head"><h2>Project directory</h2><span class="muted"><?=count($rows)?> project(s)</span></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Start date</th><th>Employees assigned</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="3" class="empty">No projects have been created yet.</td></tr><?php endif; foreach($rows as $r): ?><tr><td><b><?=e($r['project_name'])?></b></td><td><?=e($r['start_date'])?></td><td><?=number_format($r['assigned_count'])?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include 'includes/footer.php'; ?>